    bag_examples_v2_toast: "🎁 Novos exemplos na sua bolsa: ideias de presente, uma lista para o hotel e outra para o voo ✨",
    faq_a_bag_examples_list: "Uma bolsa nova vem com exemplos que você pode alterar ou excluir como qualquer outra coisa: Casa (compras, receitas, refeições da semana), Família (pequenos momentos, uma lista para a festa de aniversário, atividades e aulas), Ideias (ideias para o fim de semana, ideias de presente conforme a proximidade com a pessoa e o que fazer com o dinheiro economizado) e Viagens (lugares aonde você quer ir, mala da viagem, mala para o hotel e uma lista para o voo para o exterior). Uma bolsa que já existia recebe uma vez os mais novos, dentro dos próprios bolsos.",
    faq_q_bag_examples_list: "Quais exemplos vêm em Minha bolsa?",
    faq_a_nm_me1_guide: "O Sky – seu personagem no New Me, na primeira forma (Sky 1). Na primeira vez, logo depois de entrar, um portal de luz se abre com brilhos por todo lado e o Sky sai voando dele, explica em poucos toques o que vem pela frente e depois fica ao lado de cada pergunta: enquanto as refeições são escolhidas, ele escreve com você no livro dele, e um toque na dica dele mostra outra. No final, o Sky comemora com você e leva você para um tour curto – e quando o tour acaba, ele ainda tem mais um momentinho com você. Se você sair no meio – das perguntas ou do tour –, na próxima vez o Sky fica feliz em te ver e pergunta se é para continuar do mesmo ponto.",
