    faq_a_shop_holidays: "Na Lista de Compras, toque no presente: as festas do seu país (o das Configurações) aparecem em ordem, com as datas – calculadas sozinhas todo ano. Toque em uma festa para ver uma lista pronta do que as pessoas compram para ela; tudo vem selecionado (menos o que já está na sua lista), desmarque o que não precisar e toque em “Adicionar à lista”. Duas semanas antes de uma festa, um pequeno cartão aparece no topo da lista; ✕ o esconde até a próxima festa.",
    faq_q_shop_holidays: "Como funciona o “O que comprar para a festa”?",
    shop_hol_add: "Adicionar à lista ({n})",
