    shop_hol_btn: "O que comprar para a festa",
    shop_hol_items_title: "{holiday} – o que comprar?",
    shop_hol_not_now: "Agora não",
    faq_a_shop_delivery: "Na Lista de Compras, toque no caminhão: escolha o que vem na entrega (tudo vem selecionado), quando chega – hoje, amanhã ou outro dia – e em que horário (manhã, meio-dia, fim da tarde ou “Outro…” para o seu próprio horário). Esses itens vão para um cartão “A caminho” no topo da lista, com o dia e o horário. Quando o dia chega, “A entrega chegou?” aparece no Meu Dia (e o cartão tem “Chegou?”). Se chegou tudo, eles vão para “Comprar de novo”. Se falta alguma coisa, toque no que não chegou e ele volta direto para a lista.",
    faq_a_shop_departments: "A lista se organiza sozinha pelas seções do supermercado – frutas e verduras, pães, laticínios e ovos, carnes e peixe, mercearia, congelados, bebidas, salgadinhos, limpeza, higiene, bebê e pets –, para você percorrer os corredores na ordem. A seção é reconhecida pelo nome do item. Se um item foi parar no lugar errado, toque nele e escolha a seção, ou “Outra…” para escrever a sua.",
    faq_a_shop_share_qty: "Sim. Ao lado de cada item, + adiciona mais um (×2, ×3…) e − tira um. O botão de compartilhar no topo da Lista de Compras envia a lista inteira, bem organizada por seção, pelo WhatsApp, por e-mail ou como cópia.",
    faq_a_shop_two_buttons: "Os dois significam “comprado”. ✕ é para algo que você compra uma vez só – sai da lista (e espera no arquivo 🗑️, caso tenha sido engano). ↺ é para o que você compra sempre – sai da lista e espera em “Comprar de novo”: o pequeno botão ↺ ao lado da lixeira, no fim da lista, abre essa parte, e um toque ali coloca um item de volta na lista. Em “Editar”, lá dentro, você pode tirar um item. Quando você adiciona um item, o que já comprou antes aparece como sugestão, e se ele já está na lista, simplesmente vira ×2 em vez de uma segunda linha.",
