    nm_demo_title: "Como funciona uma troca",
    faq_a_new_me_challenge_journal: "Quando um desafio termina – grande, mini ou o desafio da semana –, a comemoração mostra um botão 📝 Como foi?, que abre uma página no diário de desafios: como você se sentiu (cinco carinhas), o que ajudou, o que foi difícil e o que eu levo disso – nada é obrigatório, e também pode ficar para mais tarde. O diário é um diamante na mochila mágica: cada desafio terminado com a data e o que foi escrito, o mais recente primeiro – toque em um para ler, editar ou compartilhar (só o que está na página é compartilhado). Um desafio terminado também ganha uma medalha nas conquistas, em “Desafios que terminei”. O diário de desafios é separado do diário comum.",
    faq_q_new_me_challenge_journal: "O que é o diário de desafios?",
