    nm_chj_save: "Salvar no diário de desafios",
    nm_chj_saved: "Salvo no diário de desafios",
    nm_chj_share_text: "Terminei um desafio no New Me ✨",
    nm_chj_take: "O que eu levo disso?",
    nm_chj_title: "Diário de desafios",
    nm_chj_write: "Escrever como foi",
    nm_swap_time: "Horário",
    faq_a_ai_reminder_in_text: "Sim – escreva junto com a tarefa, por exemplo “amanhã às 17:00 buscar o pacote, com um lembrete uma hora antes”. O lembrete fica salvo na própria tarefa: uma hora antes, meia hora, um dia antes e assim por diante, e “me lembre” sem horário significa 10 minutos antes. Um lembrete escrito no texto tem prioridade sobre o campo de lembrete na mesma janela.",
    faq_q_ai_reminder_in_text: "Posso pedir um lembrete ao assistente de IA no mesmo pedido?",
    myday_meals_all_done: "Todas as refeições de hoje estão marcadas 🍽️",
    nm_tour_week_text: "Um pequeno desafio para a semana. ✓ todo dia – e uma chave no final.",
    books_home_chip: "{title} · pág. {page}",
    books_home_of: "de {total}",
    books_home_off_toast: "O livro saiu da tela inicial",
    books_home_on_toast: "O livro está na tela inicial 📖",
    books_home_pin: "Na tela inicial",
    books_home_q: "Em que página estou?",
    books_home_save: "Salvar",
    faq_a_books_home_chip: "Sim. No Cantinho da leitura, no cartão de um livro que você está lendo, toque em 📌 Na tela inicial. Um botãozinho com o livro e a página aparece embaixo da saudação na tela inicial – toque nele, digite o novo número da página e salve, e o progresso é registrado (no Cantinho da leitura também). Tocar em 📌 de novo o remove. Vários livros podem ficar lá juntos – um botão para cada um – e é igual em todos os dispositivos.",
    faq_a_new_me_week_challenge: "Um pequeno desafio de uma semana, escolhido por você. No corredor há um cartão grande: “No que você gostaria de trabalhar esta semana?” – toque nele, escolha uma área (comigo, com os outros, aprender e crescer, calma, pequenos passos corajosos, casa e rotina) e um desafio, e decida quando ele começa. Os mesmos desafios também estão na tela de desafios, em 🌱 Crescimento pessoal. Todo dia se marca ✓ no cartão (um dia livre por semana), e cada semana que termina traz uma chave nova para o mundo secreto. “Ler 2 páginas por dia” é marcado sozinho pelas páginas registradas no Cantinho da leitura. Quando a semana termina, 📌 Manter como tarefa diária o adiciona à Minha Rotina no horário que você escolher, com um ✓ por dia. Só um desafio da semana roda por vez; os desafios grandes e os mini desafios continuam em paralelo.",
    faq_a_room_genie: "Na varanda de frente para o mar, um toque na lâmpada de Aladim faz sair o espírito da floresta – e começa uma conversa: qual é o seu desejo (o que você gostaria de mudar na sua vida), como vai ser quando ele se realizar, o que é difícil no caminho e como a situação de agora pode virar algo bom. Depois, mais ou menos quanto tempo vai levar, um primeiro passo pequeno e mais dois, e um “se… então…” para quando ficar difícil. No fim aparece o desejo inteiro passo a passo, e ele pode virar uma meta em Minhas Metas (os passos viram marcos no caminho, com data conforme o tempo escolhido; lá dá para mudar tudo) ou ser salvo no diário – e então o espírito se despede. Nada é salvo se nenhuma das duas opções for escolhida. A partir da segunda visita, o espírito pergunta primeiro se você gostaria de mudar mais alguma coisa na sua vida: sim – a mesma conversa; agora não – um lembrete para alcançar as metas já definidas. O espírito aparece uma vez por dia: depois que um desejo é salvo (ou depois de “Agora não”), ele descansa até amanhã. As perguntas seguem um jeito conhecido de transformar um desejo em plano: desejo, resultado, obstáculo e plano.",
    faq_q_books_home_chip: "Posso ver meu livro e a página na tela inicial?",
    faq_q_new_me_week_challenge: "O que é o desafio da semana?",
