    faq_a_new_me_game: "No New Me, os botões do jogo ficam sempre no mesmo lugar – no corredor, no quarto secreto e em toda a floresta; só a pintura do meio muda. No alto: o dia na jornada, as chaves, a sequência e a energia de hoje (quanto do plano já foi comido), e logo abaixo a próxima missão – a próxima refeição no horário dela (um toque abre, com ✓ Já comi). Na lateral: o dia todo, desafios e minha jornada, e ao lado deles o desafio da semana – seus 7 dias e um ✓ para hoje. Embaixo: a mochila mágica (tudo do New Me – mapa do mundo, minha jornada, lista de compras, conquistas, diário de desafios, medidas, fotos de evolução, calendário mensal, tabela do dia, lembretes, cardápio em PDF e ajustes; ela abre como uma tela própria). O mapa do mundo, a primeira coisa na mochila, mostra todos os lugares da floresta – toque num lugar para ir até lá; um lugar trancado mostra quantas chaves precisa. O Sky é o seu personagem na trilha na floresta: começa como Sky 1, depois de alguns desafios (4 chaves) cresce e vira Sky 2, e perto do fim (9 chaves) Sky 3 – com uma transformação que dá para ver acontecendo. Toque no Sky para ver todas as fases – qualquer fase já alcançada pode ser escolhida de novo, então uma anterior pode voltar. O Sky flutua – dá para arrastá-lo com o dedo ou o mouse, e a entrada que ele tocar se abre (numa trancada aparece quantas chaves faltam). O Sky também vai junto para cada quarto e lugar e flutua onde você o deixar: arraste-o para qualquer lugar, e arraste o anel brilhante embaixo dele para girá-lo por completo; ele fica virado para o lado em que se move (no computador: as setas o movem, Q e E o giram). No corredor, o pequeno 🏠 abaixo da barra superior volta para a tela inicial; em cada quarto e lugar, o botão no mesmo canto volta para o corredor.",
    faq_q_new_me_game: "Como funcionam os botões do jogo, o mapa do mundo e o Sky?",
