    faq_a_new_me_menu_build: "Primeiro, o questionário pergunta quais refeições você faz e quando (2 refeições + um lanche, 2 refeições + um jantar leve, ou os dois), e se há algo à noite – para comer ou beber, o quê e a que horas. Com “2 refeições + um lanche”, as refeições são o almoço (11:30) e o jantar (19:00), com o lanche às 16:00. Depois aparecem todas as opções dessas refeições. Escolha até 2 favoritas por refeição – o cardápio mostra “isto ou aquilo”. Em algumas opções (pita e pasta, flocos de milho com leite, algo leve) você escolhe até 3 coisas de que gosta, cada uma na sua porção, e o cardápio mostra “isto ou aquilo ou aquilo outro”; as calorias acompanham o que você escolheu. Café e bebidas funcionam do mesmo jeito. Cada escolha é equilibrada, então o dia soma exatamente 1.300 ou 1.500. Para mudar quando quiser: ⚙️ Ajustes → 🍽️ Monte seu cardápio, ou “Escolha até 3 de que você gosta” no cartão da refeição.",
    faq_q_new_me_menu_build: "Como o cardápio do New Me é montado?",
