    faq_a_myday_water_toggle: "Sim. O copo de água no “Meu Dia” (com + para mais um copo) aparece por padrão. Para ocultá-lo, desative “Mostrar a água no ‘Meu Dia’” em Configurações > Personalização e calendário. Nada é apagado – o Controle de Água continua funcionando, e ao reativar, o copo volta.",
    faq_q_myday_water_toggle: "Posso ocultar a água no “Meu Dia”?",
    myday_water_toggle_label: "Mostrar a água no “Meu Dia”",
    faq_a_routine_newme_sync: "Com o New Me, o ⚙️ da Minha Rotina tem um botão “Sincronizar com o New Me”. Ligado (o padrão), as refeições de hoje do New Me aparecem no Meu Dia e na Minha Rotina – no lugar das refeições da rotina que foram ocultadas. Desligado, as refeições do New Me saem dos dois e a rotina volta exatamente a como era. Nada é apagado – ligar de novo traz tudo de volta e pergunta quais refeições da rotina ocultar.",
    faq_q_routine_newme_sync: "Como ligo ou desligo a sincronização do New Me com a Minha Rotina e o Meu Dia?",
