    faq_a_food_list_languages: "A lista de alimentos integrada começou com comidas israelenses e seus nomes em hebraico. Nos outros idiomas, cada alimento aparece com o nome em inglês, e a busca encontra qualquer nome em inglês que conheça (por exemplo, 'broth' encontra Clear soup); alimentos que só têm nome em hebraico não aparecem. O que não estiver na lista pode ser escrito com suas próprias palavras – a estimativa com IA funciona em todos os idiomas.",
    faq_q_food_list_languages: "Por que a lista de alimentos mostra nomes em inglês, e menos alimentos, no meu idioma?",
    settings_copyright_line: "© 2026 todos os direitos reservados. app desenvolvido por eden zabari.",
    workout_ready_replace_btn: "Substituir",
    faq_a_sport_workout_ai: "Em Meus treinos → ⋯ → Plano com IA (e, com a tabela vazia, também no bloco ao lado dos planos prontos). Responda com alguns toques – quantas vezes por semana, quando, local, nível e objetivo, quase todos também com \"Outro\" – e, se quiser, adicione uma linha livre, como um joelho sensível ou correr 5 km até o verão. A IA cria uma semana inteira: tipos de treino, dias, horários, duração, intensidade, exercícios e dias de descanso. Nada é salvo antes de uma prévia: \"Colocar na minha tabela\" (no lugar da tabela ou junto com ela), \"Outra sugestão\" (até 3 vezes) ou \"Mudar respostas\". O plano é moderado de propósito, e se você mencionar dor ou lesão recebe opções leves e a sugestão de consultar um profissional. Ele usa a mesma cota de IA da agenda e da rotina: 5 vezes grátis e 60 por mês com Premium.",
    faq_q_sport_workout_ai: "Como crio um plano de treino com IA?",
    workout_ai_add: "Junto com a minha tabela",
    workout_ai_again: "Outra sugestão",
