    workout_ai_other: "Outro",
    workout_ai_replace: "No lugar da minha tabela",
    workout_ai_title: "Plano de treino com IA",
    workout_ai_when_evening: "Noite",
    workout_ai_when_label: "Quando",
    workout_ai_when_morning: "Manhã",
    workout_ai_when_noon: "Meio-dia",
    workout_ai_when_ph: "ex.: depois do trabalho, ou 17:30",
    workout_ai_working: "Criando seu plano…",
    faq_a_sport_workout_jar: "Cada tipo de treino tem sua própria estrela colorida – corrida rosa, caminhada verde, natação azul e assim por diante. Cada treino registrado nesta semana, pela tabela ou separado, deixa cair sua estrela no pote no topo de Meus treinos, e o pote vai enchendo até a sua meta semanal (toque nele para mudar a meta). Ao bater a meta, o pote brilha. O potinho ao lado conta quantas semanas seguidas você o encheu.",
    faq_q_sport_workout_jar: "O que são as estrelas coloridas e o pote em Meus treinos?",
    faq_a_sport_workout_gcal: "Sim – em ⋯ → Google Agenda (depois de conectar o Google Agenda em Configurações). Cada treino com horário vira um evento que se repete toda semana nos seus dias, e as mudanças no app o atualizam. Os lembretes vêm só do app, então o Google não adiciona os seus, e os treinos nunca aparecem duas vezes no app. Tocar de novo remove do Google Agenda só os treinos.",
    faq_q_sport_workout_gcal: "Meus treinos podem aparecer no Google Agenda?",
    workout_gcal_btn: "Google Agenda",
    workout_gcal_error: "Não foi possível atualizar o Google Agenda – vamos tentar de novo na próxima mudança",
    workout_gcal_not_connected: "Primeiro conecte o Google Agenda em Configurações",
    workout_gcal_off_toast: "Os treinos foram removidos do Google Agenda",
    workout_gcal_on_toast: "Seus treinos estão no Google Agenda",
    faq_a_sport_workout_reminder: "Sim – num treino, Lembrete: 10 minutos, 30 minutos ou uma hora antes, ou um tempo personalizado (o treino precisa de um horário). Ele toca como seus outros lembretes, uma vez e em um só lugar: no app se estiver aberto, senão no celular. \"Feito\" registra o treino no histórico, e \"Ainda não\" lembra de novo em 5 minutos.",
    faq_q_sport_workout_reminder: "Posso receber um lembrete antes de um treino?",
    workout_reminder_30min: "30 minutos antes",
    workout_reminder_label: "Lembrete",
    workout_reminder_need_time: "Adicione um horário para receber um lembrete",
    faq_a_sport_workout_share: "Em ⋯ → Compartilhar, a semana vira uma imagem de vidro nas cores do seu tema, com um link discreto para o app (no celular vai direto para o menu de compartilhar; no computador a imagem é salva). ⋯ → PDF para imprimir abre uma página limpa com a semana inteira e um quadradinho para marcar ao lado de cada treino e exercício – escolha \"Salvar como PDF\" ou imprima. O plano também aparece no relatório de dados em Configurações, na parte de Esporte.",
    faq_q_sport_workout_share: "Como compartilho ou imprimo minha semana de treinos?",
    share_image_saved: "A imagem foi salva – você pode anexá-la",
    share_save_image: "Salvar a imagem",
    workout_pdf_btn: "PDF para imprimir",
    workout_share_btn: "Compartilhar",
    faq_a_sport_workout_board: "Em ⋯ → Quadro semanal cada dia é uma coluna: arraste um treino para outro dia (no celular, toque e segure antes). Num treino, \"Também na Minha Rotina\" coloca-o na sua rotina no horário e nos dias dele, e as mudanças ficam sincronizadas nos dois sentidos; num item da Minha Rotina, \"Adicionar aos meus treinos\" faz o contrário. Um ✓ em qualquer um conta nos dois, e no Meu Dia ele aparece uma vez só – no chip ao lado da água.",
    faq_q_sport_workout_board: "Como movo um treino para outro dia e ligo à Minha Rotina?",
    routine_in_workouts_btn: "Abrir nos meus treinos",
    routine_to_workout_btn: "Adicionar aos meus treinos",
    routine_to_workout_done: "Adicionado aos meus treinos 💪",
    workout_delete_confirm_routine: "Ele sai do plano e da Minha Rotina. Os treinos já registrados no histórico ficam.",
    workout_moved: "Movido para {day}",
    workout_routine_need_time: "Adicione um horário para colocar na Minha Rotina",
    workout_routine_toggle: "Também na Minha Rotina",
    workout_view_board: "Quadro semanal",
    workout_view_timeline: "Linha do tempo",
    faq_a_sport_workout_plan: "Em Monitoramento de Treinos, em \"Meus treinos\": + Treino – tipo, dias, horário, duração, intensidade e local (também \"Outro\"). Treinos de força, funcional e natação podem ter uma lista de exercícios, e Descanso marca um dia de descanso. Você também pode começar com um plano pronto. O treino de hoje aparece em destaque, com a semana inteira abaixo; ✓ registra no histórico de treinos junto com a intensidade. Em ⋯ você define uma meta semanal (treinos ou minutos) – cada treino feito deixa cair sua estrela no pote.",
    faq_a_sport_workout_today: "Em Meu Dia, ao lado da água, um pequeno chip mostra o treino de hoje – um toque abre os detalhes, ✓ e ▶. ▶ inicia um cronômetro que continua no chip da tela inicial, e \"Concluir\" registra o treino com o tempo real. Se o desafio \"Duas semanas de movimento\" do New Me estiver ativo, um treino registrado conta nele sozinho.",
    faq_q_sport_workout_plan: "Como planejo minha semana de treinos?",
