    faq_a_new_me_magic_themes: "Cinco temas brilhantes que vêm com o New Me: Floresta encantada, Poeira de estrelas, Fada das rosas, Aurora mágica e Entardecer dourado. Escolha um dentro do New Me (⚙️ Ajustes > Cores) ou em Configurações > Aparência e tela, e um pincel de brilhos pinta a tela com ele. Um tema mágico coloca brilhos no app inteiro e a cada toque. Dá para voltar a qualquer outro tema quando quiser.",
