    apptour_focus_text: "Tudo sai da frente, menos a única coisa de agora – com um ✓ grande. Depois aparece a próxima.",
    apptour_m_presets_text: "Suas refeições salvas em um só lugar: busca, usadas recentemente, por horário do dia – e ＋ adiciona uma a hoje.",
    apptour_night_text: "🌙 escurece o app inteiro; ☀️ traz o dia de volta.",
    apptour_noteline_text: "Escreva e toque em ➤ – fica salvo nas suas notas. 📝 no começo troca para 🛒 compras ou 🍎 uma refeição salva.",
    apptour_search_text: "Notas, compras, calendário, receitas, cadernos, metas, tabelas e livros – uma busca encontra tudo.",
    faq_a_new_me_ai_menu: "Antes do cardápio, o questionário pergunta quais refeições você faz e quando (2 refeições + um lanche, 2 refeições + um jantar leve, ou os dois), se você come algo pequeno à noite e a que horas, o que você não come e como toma café ou chá. Depois a IA monta 3 opções para cada refeição – cada uma do tamanho da sua parte do dia, então o dia continua somando exatamente 1.300 ou 1.500 – e ideias de bebidas, que ficam salvas como suas bebidas frequentes. Escolha até 2 favoritas por refeição; as opções do cardápio original ficam logo abaixo, e em 🔄 Trocar aparecem depois do seu cardápio pessoal. 🔄 Outras opções monta uma nova rodada (3 vezes por questionário). Para mudar as respostas ou montar um novo cardápio quando quiser: ⚙️ Ajustes → ✨ Cardápio pessoal (IA).",
    faq_q_new_me_ai_menu: "Como funciona o cardápio pessoal do New Me?",
