    apptour_s_gcal_inside_text: "Conecte o Google Calendar uma vez, e eventos e tarefas ficam sincronizados nos dois sentidos.",
    apptour_s_menu_text: "Tudo o que dá para ajustar está aqui, em cinco grupos. Vamos abrir 👇",
    apptour_skip_part: "Pular esta parte",
    apptour_start: "Começar o tour",
    nm_sales_premium: "Inclui todo o Premium",
    nm_unlock_premium: "E todo o Premium também foi liberado.",
    settings_sub_status_newme: "O Premium está incluído no seu New Me.",
    room_back_to_shelf: "Para a estante",
    faq_a_new_me_day_total: "Cada dia fecha exatamente no plano: as refeições, cerca de 150 calorias para café e bebidas ao longo do dia e o que foi escolhido para a noite – algo pequeno para comer ou algo para beber. Para a noite, escolha até 3 de que você gosta (por exemplo uma banana, um iogurte ou 2 quadradinhos de chocolate amargo; ou chá de ervas, chá com um pouco de leite ou leite morno), e as calorias deles são tiradas das refeições. Cada escolha se equilibra sozinha: uma opção menor ou maior, uma refeição retirada, o café da manhã pequeno e a refeição pequena que vem com ele, ou a noite – a diferença é somada às refeições ou tirada delas, cada uma conforme o seu tamanho, e embaixo de cada refeição aparece quanto (+ ou −) e o que acrescentar ou tirar. Uma refeição já marcada fica como foi registrada. No questionário, cada refeição mostra o seu ajuste, e um quadradinho mostra refeições, bebidas, a noite e o total. Com vontade de outra coisa nesse dia? Mantenha o total nas mesmas calorias ou menos.",
    faq_q_new_me_day_total: "Como um dia do New Me fecha exatamente em 1.300 / 1.500, e onde entram as bebidas?",
