    nm_swap_balanced: "{n} calorias divididas entre as refeições, para o dia fechar em {plan}",
    books_quotes_chip: "Citações",
    faq_a_book_quotes: "Na estante do quarto secreto (Citações), ou no pequeno selo 💬 Citações do Cantinho da leitura – é a mesma lista. Toque em \"+ Citação\", escreva a frase e escolha o livro do seu Cantinho da leitura, ou digite outro título em \"✏️ Outro\"; o autor é opcional. ✏️ edita uma citação e 🗑️ a exclui. As citações são marcadores que você desliza – 🎨 no topo troca para fotos ou um mural de cartões.",
    faq_a_room_wish_jar: "Na estante do quarto secreto há um pote de vidro para sonhos. Toque no potinho da prateleira de cima (ou Estante > O pote dos desejos) e escreva como você quer que sua vida seja – o mais ousado que quiser, sem certo ou errado. Cada desejo vira um bilhete dobrado e cai no pote. “Tirar um bilhete” abre um ao acaso, e cada bilhete também pode ser aberto sozinho. A partir da segunda vez que você abre o mesmo desejo, dá para transformá-lo em meta e dividi-lo em passos pequenos. Uma vez por semana aparece, com delicadeza, um bilhete com um dos seus desejos – sem pressão, só um lembrete de para onde você vai.",
