    room_wish_to_goal: "🎯 Transformar em meta, em passos pequenos",
    room_wish_written: "Escrito em {date}",
    faq_a_saved_meals_page: "As refeições salvas têm uma página própria: Nutrição e Métricas > ⭐ Refeições salvas (ou ⭐ no menu). A busca no topo encontra uma refeição pelo nome ou por um ingrediente, \"Usadas recentemente\" mostra o que você adicionou por último, e as abas (Café da manhã, Almoço, Jantar, Sopas…) mostram cada momento do dia. \"+ Hoje\" adiciona uma refeição ao Registro Diário de Refeições de hoje, no próximo espaço livre. Toque em uma refeição para editá-la ou excluí-la, e ＋ no topo adiciona uma nova.",
