    presets_tab_soup: "Sopas",
    presets_tab_sweet: "Doces",
    faq_a_notes_sticky_look: "As notas são uma lista curta de cartões de vidro – 🎨 no topo de Notas muda o visual de todas as Notas (a lista, os botões dos dias lá em cima e a janela onde se escreve uma nota): vidro, lista limpa, fichas ou fita washi. Uma nota sendo arrastada mantém exatamente o próprio visual e a própria cor. Toque no texto de uma nota para abri-la – lá você pode editá-la, mudar as cores e ver quando foi escrita pela última vez. Toque em ○ quando estiver feita, e × a move para o arquivo (🗑️ no fim da lista a traz de volta). Arraste por ⠿ para mudar a ordem, para baixo de “Mais tarde” ou para um dia lá em cima. ! marca uma nota como urgente – ela sobe suavemente para as primeiras linhas, com uma pequena etiqueta “Urgente”; outro toque tira a marcação.",
    faq_q_notes_sticky_look: "Como abro, edito ou removo uma nota?",
    note_to_archive_btn: "Mover para o arquivo",
    faq_a_routine_clash: "Se nesse horário já houver um item nos mesmos dias, aparecem duas opções: \"Substituir\" – o novo item fica com esse horário e você escolhe outro horário para o que estava lá (ao editar um item existente, o horário anterior dele é sugerido, então os dois simplesmente trocam), ou \"Os dois\" – ambos ficam no mesmo horário, um embaixo do outro. Se os dias forem diferentes (por exemplo, um de domingo a quinta e o outro na sexta), nada é perguntado.",
    faq_q_routine_clash: "O que acontece quando coloco um item na rotina num horário já ocupado?",
    routine_clash_both: "✌️ Os dois – ambos às {time}",
    routine_clash_move_btn: "Mover e salvar",
    routine_clash_move_to: "Para que horário mover \"{title}\"?",
    routine_clash_replace: "🔄 Substituir – e mover \"{title}\" para outro horário",
    routine_clash_title: "Às {time} já tem: {title}",
    faq_a_new_me_coffee: "Abaixo do cardápio de hoje há um resumo curto: quantas calorias somam todas as refeições do dia, quanto resta para café e bebidas, e botões do café e das bebidas escolhidos – um toque adiciona às Bebidas. Em “Escolha até 3 de que você gosta”, abaixo dos botões (e no questionário), você escolhe o que aparece: água / água com gás, chá de ervas, uma bebida diet, preto / americano (~5), chá com um pouco de leite (~25), café à base de água com até 100 ml de leite ou bebida vegetal (~50), chocolate quente leve, leite morno ou café comum / com leite (~120).",
    faq_q_new_me_coffee: "Onde adiciono o café, e como sei quanto resta para o dia?",
