    nm_late_room_line: "Algo pequeno antes de dormir · restam ~{n} kcal hoje",
    faq_a_recipe_examples: "Abaixo das suas receitas há receitas de exemplo: cafés da manhã, saladas, sopas, pratos principais, acompanhamentos, lanches, sobremesas e pratos veganos, cada uma com o tempo de preparo, as calorias por porção e quantos gramas pesa uma porção. Toque numa receita para abri-la, e \"Salvar em Minhas Receitas\" cria a sua própria cópia, que você pode editar. As etiquetas de categoria filtram, e tocar de novo na mesma etiqueta mostra tudo.",
    faq_a_recipe_grams: "Dentro de uma receita, ao lado das calorias, aparece \"1 porção ≈ X g\". Nas suas próprias receitas, preencha \"Gramas por porção\" (e o tempo de preparo, se quiser) no formulário da receita: os dois são opcionais, e o tempo aparece na faixa colorida da receita.",
