    recipe_saved_example_toast: "Salva em Minhas Receitas: lá você pode editá-la",
    recipes_examples_title: "Receitas de exemplo",
    faq_a_recipe_scan_multi: "Sim. Em \"Adicionar Receita\", toque em 📷 e escolha uma foto ou várias (até 6; um PDF também funciona). Cada uma aparece numa lista curta onde você escolhe o que ela mostra: Tudo, Ingredientes ou Preparo, e \"➕ Mais uma foto\" adiciona outras. Depois toque em \"✨ Escanear a receita\": a IA junta tudo numa só receita, na ordem e sem linhas repetidas, e conta como um único escaneamento. Várias fotos escolhidas em 📷 Foto no assistente de IA também abrem aqui.",
    faq_q_recipe_scan_multi: "Posso escanear uma receita a partir de várias fotos, como os ingredientes e o modo de preparo separados, ou duas páginas?",
