    faq_a_note_written_at: "Toque no texto da nota para abri-la. Dentro, abaixo do texto, aparece quando ela foi escrita pela última vez, com data e hora exatas. Só uma mudança no próprio texto atualiza isso: arquivar e restaurar, marcar ✓, as cores ou mover a nota não mudam.",
