    note_written_at: "Escrita pela última vez: {date}",
    faq_a_new_me_month: "Na mochila mágica → Calendário mensal: cada dia tem uma cor conforme quantas refeições foram marcadas, as setas ‹ › passam de um mês para outro, e embaixo do calendário aparece a média diária de calorias do mês. Um toque num dia mostra quantas refeições foram marcadas e quantas calorias foram comidas naquele dia.",
    faq_q_new_me_month: "Onde vejo o mês para trás e minha média de calorias no New Me?",
