    nm_month_day_line: "Refeições marcadas: {checks} · calorias: {kcal}",
    nm_extra_line_small: "{n} calorias para esta refeição, do café da manhã pequeno – por exemplo {ideas}",
    faq_a_new_me_small_breakfast: "Um café da manhã leve (cerca de 170 kcal): uma pita de espelta (até 100 kcal) com uma pasta ou queijo, além de um legume – escolha até 3 de que você gosta, por exemplo 1 colher de chá de creme de chocolate, 1 colher de chá de pasta de amendoim ou uma fatia de queijo prato (até 22%). Como ele é pequeno, vem junto “E mais uma refeição pequena” em outro horário (uma hora e meia depois, por exemplo 11:30 → 13:00 – dá para escolher qualquer outro horário): mais uma pita e pasta, iogurte proteico e fruta, biscoitos de arroz e queijo, cereal com leite ou meia pita e ovos – até cerca de 200 kcal, com o seu próprio ✓. O que ainda sobra é dividido entre as outras refeições, e cada refeição mostra quanto ganhou, então o total do dia fica como no plano. Dá para escolher no questionário ou trocar para ele só hoje com 🔄 – por exemplo, quando o café da manhã atrasa.",
    faq_q_new_me_small_breakfast: "O que é o “café da manhã pequeno” no cardápio do New Me?",
