    faq_a_ai_icon: "Sim – em Configurações > Aparência e tela. A bolha suave é o padrão, e com o Premium também dá para escolher um cérebro flutuante ou um robô.",
    faq_a_new_me_favorites: "Sim. No questionário (e ao refazê-lo pelos ajustes), dá para escolher até 2 opções para cada refeição. A primeira aparece no cardápio, com uma linha “ou” embaixo para a segunda – um toque nela troca para ela só hoje. E se o café da manhã não foi comido na hora, “⏰ Mais tarde” o passa para mais tarde no dia, sem mudar as calorias.",
    faq_a_theme_mode: "Alguns temas especiais ficam mais bonitos no escuro – Aquarela, Aurora boreal, Barbie e os dois temas de brilho –, então escolher um deles muda o app para o modo escuro, e escolher qualquer outro tema (o foguete também) muda para o claro. Preto e Cinza-escuro continuam escuros. Dá sempre para mudar depois com 🌙 no menu ou com Modo Claro nas configurações.",
    faq_a_water_month: "No controle de água. Cada registro do dia mostra a hora em que foi adicionado, e \"Tabela mensal\" abre o mês inteiro: cada dia mostra quantos litros foram bebidos (✓ quando a meta diária foi alcançada), e um toque num dia mostra os registros dele com os horários.",
