    dev_sim_panel_title: "PM – só para você",
    faq_a_new_me_weight_optional: "Não. Tanto o peso atual quanto o peso-meta do questionário são opcionais. Se uma pesagem for adicionada depois (⚖️ Peso em “Minha jornada” no New Me, ou no controle de peso), o progresso é contado a partir da primeira.",
    faq_q_new_me_weight_optional: "Preciso informar meu peso no New Me?",
    nm_unlock_desc: "O cardápio, os desafios e a jornada estão prontos – passo a passo, em conjunto.",
    nm_unlock_title: "New Me desbloqueado!",
    room_reveal_star: "Uma nova estrela acendeu no telescópio do telhado ✨",
    faq_a_room_records: "A vitrola fica no quarto desde o começo, no toco de árvore ao lado da poltrona. Os discos dela abrem no YouTube os clipes oficiais de grandes sucessos dos últimos anos, e abaixo há cinco melodias calmas que tocam aqui mesmo no quarto – o disco gira enquanto elas tocam, e “⏹ Parar” encerra a música.",
    faq_a_room_roof_gifts: "Eles chegam com a 8ª chave. Um toque no telescópio permite olhar através dele: o céu noturno de pertinho (arraste, ou use as setas, para olhar ao redor), e seus desafios concluídos formam nele uma constelação, uma estrela para cada desafio; um toque numa estrela mostra qual foi. Um toque no bauzinho o abre (por enquanto está vazio) e outro toque o fecha.",
    faq_q_room_records: "O que tem na vitrola do quarto secreto?",
    faq_q_room_roof_gifts: "O que são o telescópio e o baú no telhado?",
    room_chest_letter: "Uma cartinha para você",
    room_chest_letter_1: "Cada pequeno passo do caminho foi real – e todos contam.",
    room_chest_letter_2: "Ter carinho consigo é parte do caminho, não uma pausa nele.",
