    faq_a_new_me_preview: "Sim. A página do New Me começa com um vídeo curto do que acontece lá dentro: o questionário, as luminárias do corredor, a mochila, os desafios e as chaves. Abaixo está tudo o que vem incluído, uma espiada em um dia e respostas curtas.",
    faq_q_new_me_preview: "Dá para ver o New Me antes de comprar?",
