    ai_chat_food_edit: "✏️ Corrigir calorias / proteína",
    ai_chat_food_invalid: "As calorias precisam ser um número maior que 0",
    ai_chat_food_updated: "Atualizado:",
    faq_a_ai_chat_food_fix: "Sim. Embaixo da resposta no chat, toque em ✏️ Corrigir calorias / proteína, mude os números e toque em Salvar. Só muda o que acabou de ser adicionado – mesmo que tenha se juntado a um lanche que já estava lá. A IA pode errar, então vale conferir.",
    faq_a_new_me_home_btn: "Com o New Me, um pequeno 💎 ao lado do modo foco, no alto da tela inicial, abre o cardápio de hoje. As refeições de hoje também aparecem no Meu Dia, cada uma com um ✓.",
    faq_a_routine_item_days: "Sim. Toque no item na Minha Rotina e escolha os dias dele em 📅 Dias – por exemplo, só de segunda a sexta. Nos outros dias ele não aparece no Meu Dia e não tem ✓; na Minha Rotina ele continua, mais apagado, com os dias ao lado. O cartão que pergunta sobre um item depois de 3 dias sem ✓ conta só os dias desse item.",
    faq_q_ai_chat_food_fix: "Dá para corrigir as calorias ou a proteína depois que o assistente registra a comida?",
    faq_q_new_me_home_btn: "Onde fica o New Me na tela inicial?",
    faq_q_routine_item_days: "Um item da Minha Rotina pode ficar só em alguns dias?",
    routine_item_days_label: "📅 Dias",
    home_note_meal_ph: "Buscar uma refeição salva…",
    menu_quick_search: "Busca rápida",
    nm_times_hint: "Dica: você pode colocar o horário mais tarde em que costuma fazer cada refeição – por exemplo, 9:00 se costuma comer por volta das 8.",
    room_game_marquee: "No caminho – paramos para aproveitar",
    room_sand_erase_aria: "Esfregue para apagar o que está escrito",
    faq_a_home_note_line: "Escreva na linha no meio da tela inicial e toque em ➤ (ou Enter) – ela é salva em Notas. Toque em 📝 no começo da linha e ele vira 🛒: aí o que você escrever vai para a Lista de Compras. Toque mais uma vez para 🍎: digite algumas letras, suas refeições salvas que combinam aparecem, e um toque registra uma nas refeições de hoje. Com 🎤 você pode simplesmente falar.",
    faq_a_night_mode: "Abra o menu ☰ e toque em 🌙 no alto – o app inteiro fica escuro. ☀️ no mesmo lugar traz o dia de volta. Também está em Configurações, em Modo Claro.",
    faq_q_home_note_line: "Como escrevo uma nota rápida pela tela inicial?",
    faq_q_night_mode: "Como mudo para o modo noite?",
    menu_day_mode: "Modo dia",
    menu_night_mode: "Modo noite",
    faq_a_secret_room_yoga: "No fim da trilha na floresta há um portão luminoso e, atrás dele, perto de uma cachoeira, as criaturas da floresta – Lumi, Puffi, Nixie e Sparklet – se sentam em semicírculo sobre seus tapetes, e Flora, a professora de ioga, se senta de frente para elas no único tapete que fica sobre a pedra. Toque na Flora: ela abre os olhos, tudo se aproxima e a conversa começa devagar, com tempo para ler – Flora pergunta como todos estão, cada criatura responde com o próprio nome (com um pequeno desenho de quem está falando ao lado de cada linha), e depois ela pergunta como você se sente com as pessoas próximas. A conversa segue conforme suas respostas – pessoas boas, alguém difícil ou um pouco de solidão. Cada caminho termina com uma pequena missão (ela pode ir direto para o Meu Dia; quando a missão é escrever algo, há um lugar para escrever, e fica salvo no diário mágico) e uma postura com três respirações em conjunto. ↩ volta um passo e ✦ começa uma conversa nova. A próxima chave abre a cachoeira: sentar na pedra faz tudo sumir, e só fica o som da água. Ao se debruçar sobre o lago, uma pergunta sobe da água – o que o seu eu verdadeiro faria hoje? – e a resposta vira uma pequena tarefa no Meu Dia. É um momento gentil, não um substituto para conversar com um profissional.",
    faq_q_secret_room_yoga: "O que acontece na ioga da floresta?",
    room_back_to_forest: "Voltar à trilha",
    room_back_to_yoga: "Voltar à ioga",
