    room_waterfall_rock_aria: "Sentar na pedra",
    room_yoga_guide_aria: "Falar com a Flora",
    yg_g_alone: "Obrigada por compartilhar. Isso acontece com todo mundo às vezes.",
    yg_g_alone_q: "O que faria bem, mesmo que só um pouquinho?",
    yg_g_critic: "Uma crítica pode doer por muito tempo. Ela fala de um momento – não da pessoa inteira.",
    yg_g_end: "Obrigada por vir ao círculo. Você pode voltar quando quiser.",
    yg_g_gate: "Você pode colocar um limite. Um limite não é um muro – é um portão.",
    yg_g_good: "Que lindo 💛 Quem te fez bem esta semana?",
    yg_g_good_msg: "Vale a pena dizer às pessoas boas que elas são boas. Um pequeno obrigado pode fazer o dia delas.",
    yg_g_hard: "Obrigada por contar. O que mais pesa?",
    yg_g_listen: "Quando ninguém te escuta, cansa. Sua voz importa, mesmo quando é baixinha.",
