    yg_p1_alone: "Estamos aqui 💛",
    yg_p1_good: "Que bom ouvir isso! Aqueceu meu coração.",
    yg_p1_start: "Minha semana foi corrida, mas uma boa amiga ligou bem na hora certa.",
