    yg_pose_heart: "Agora coração aberto 💗 Ombros para trás, peito aberto. Três respirações em conjunto.",
    yg_pose_tree: "Agora a postura da árvore 🌳 De pé e firme, um pé na outra perna, mãos para cima. Três respirações em conjunto.",
    yg_task_good: "Mandar hoje uma pequena mensagem de agradecimento",
