    nm_time_hour: "Hora",
    nm_time_minutes: "Minutos",
    routine_time_taken: "Já existe algo nesse horário: {title}",
    faq_a_new_me_times: "No questionário do começo e, a qualquer momento, nos ajustes do New Me → “Horários das refeições”. Se a sua rotina já tem horários de refeições, eles são pegos de lá – e dá para ocultar as refeições da rotina e mostrar no lugar delas as refeições do New Me. Se não tem, você escolhe quantas refeições por dia (2 refeições + um lanche / 2 refeições + um jantar leve / 2 refeições + um lanche + um jantar leve) e quando é cada uma. Com “2 refeições + um lanche”, são o almoço às 11:30, um lanche às 16:00 e o jantar às 19:00 (dá para mudar qualquer um). Esses são os horários das suas refeições em todo lugar: no corredor, no Meu Dia, na Minha Rotina e nos lembretes. Seja qual for a escolha, as calorias do dia continuam as mesmas: o que sai é dividido entre as outras refeições.",
    faq_q_new_me_times: "Como defino os horários das minhas refeições no New Me?",
