    routine_daysoff_what: "E qual é a rotina nesses dias?",
    routine_daysoff_which: "Quais dias?",
    faq_a_secret_room_diary: "Só você. As páginas do diário ficam salvas na sua conta, então estão em todos os seus aparelhos, e ninguém mais pode vê-las. Dá para abri-lo pelo diário mágico na escrivaninha do quarto secreto, e também pelo diário do cantinho da música. Embaixo da página nova há uma tabela mensal dobrada: um ponto marca cada dia que tem página, e tocar em um dia abre as páginas dele; ali também dá para apagar uma página. Quando o diário já está aberto, ele também pode ir para o menu principal – com o botão no próprio diário ou nos ajustes do New Me.",
    faq_a_secret_room_places: "Cada entrada do portão da floresta abre com a sua própria chave. Atrás delas: a varanda de frente para o mar (na mesinha, a lâmpada de Aladim – um toque e um espírito da floresta sai dela numa névoa mágica, dá voltas e começa uma conversa sobre o seu desejo – veja “O que faz o gênio da lâmpada?”), o violão e o diário (o violão toca uma melodia curta e calma e para sozinho, e cada um dos três discos pendurados na árvore toca a sua própria melodia mágica – um novo toque faz parar – e o diário em cima do toco é para escrever), a sala de respirar (um lago tranquilo ao pôr do sol; uma lanterna de lótus flutua na água: toque nela, escreva um desejo e ela se afasta com ele, bem longe, para o fundo do lago; com a varinha mágica dá para escrever na areia o que você quer deixar ir, e fica lá até você apagar com o dedo) e a trilha na floresta (ela se abre à noite, e tocar nas lanternas muda para o dia; do galho grande pende um balanço mágico, o banco é para sentar, e tocar na placa a aproxima: um quadro com seis perguntinhas para marcar). Numa entrada trancada aparece quantas chaves faltam. No fim da trilha, um portão luminoso leva à ioga perto da cachoeira – e de lá, à própria cachoeira.",
    faq_q_secret_room_diary: "Quem vê o diário?",
    faq_q_secret_room_places: "O que há atrás das portas do corredor?",
