    ai_chat_working_table: "Um momento, montando a tabela…",
    dev_weather_preview_label: "Prévia – só na sua conta:",
    faq_a_ai_chat: "Toque na bolha e uma conversa se abre. Escolha o que fazer – algo para o calendário, o que você comeu, a foto de uma receita ou uma tabela nova – ou simplesmente escreva, e o assistente entende sozinho. Você também pode tocar em 🎙️ e falar em vez de digitar. Para o calendário dá para escolher uma vez, toda semana ou todo dia. A resposta chega na conversa, e de lá dá para seguir para outra coisa ou abrir o calendário / o que você comeu.",
    faq_a_new_me_hall: "O New Me abre no portão de uma floresta mágica, e cada entrada nela é um lugar: a porta redonda na árvore gigante leva ao quarto secreto, o tronco oco à varanda de frente para o mar, a casinha de cogumelo ao violão e ao diário, o pequeno arco de salgueiro à sala de respirar, o grande arco de salgueiro à trilha na floresta, e o arco de flores com a escada sobe para o telhado das estrelas quando ele abre. Numa entrada trancada aparece um cadeado. Na trilha flutua o seu personagem, Sky, e em volta estão os botões do jogo: a próxima missão, o desafio da semana, a mochila mágica com todo o New Me, o mapa do mundo e as ferramentas. Um toque nas chaves lá em cima explica como as chaves são conquistadas.",
    faq_a_new_me_routine_meals: "Quando há refeições definidas no New Me e a Minha Rotina também tem refeições, o New Me pergunta se deve escondê-las e mostrar no lugar delas as refeições do New Me – para nada aparecer duas vezes. Aí a Minha Rotina mostra as refeições do New Me nos seus horários, com 💎 e um ✓; tocar no nome de uma refeição abre uma janela para escolher outra refeição ou mudar o seu horário, ali mesmo sobre a rotina. Nada é apagado: elas voltam pelos ⚙️ Ajustes do New Me → Refeições na rotina, ou desligando “Sincronizar com o New Me” no ⚙️ da Minha Rotina. Sem um New Me ativo, elas voltam sozinhas.",
    faq_a_room_computer: "É uma pequena conversa que começa com “Como está sendo o seu dia até agora?” – bem, corrido ou difícil – e segue com você passo a passo, até uma pequena missão no final (que também pode ir direto para o Meu Dia). Dá para tocar nas respostas ou escrever livremente – o que é escrito se conecta à resposta mais próxima. “↩ Voltar” volta um passo para responder de outro jeito, e “Nova conversa” recomeça a qualquer momento. Depois de um dia corrido ou difícil, dá para voltar ao computador mais tarde no mesmo dia: “Voltei...” continua a conversa. A luz verde embaixo desliga e liga o computador. Só as escolhas ficam salvas, só neste aparelho e só até o fim do dia.",
    faq_q_ai_chat: "Como converso com o assistente?",
