    dictation_mic_denied: "O microfone está bloqueado – permita pelo 🔒 ao lado do endereço no navegador, ou nas configurações do celular",
    faq_a_dictation: "Sim – toque no microfone 🎤 no canto da nota rápida ou de uma página de escrita do caderno, e fale: as palavras são escritas enquanto você fala, no idioma do app. Toque de novo para parar. Na primeira vez, o navegador pede permissão para usar o microfone. Funciona no Chrome / Android e no Safari do iPhone. No computador, é preciso um microfone e um navegador como Chrome, Edge ou Safari – se faltar algo, a mensagem diz exatamente o quê.",
    faq_q_dictation: "Posso falar em vez de digitar?",
    faq_a_secret_room: "Um quarto só seu no New Me – uma casa dentro de uma árvore gigante. Você vê uma parede de cada vez e gira com as setas (ou deslizando). A primeira chave chega depois de um ✓ numa refeição em 3 dias diferentes e abre a porta – e o quarto inteiro com ela: o computador, o jogo, a vitrola, a estante com a biblioteca dentro e o gato. Depois, cada desafio concluído (inclusive o desafio da semana) dá uma chave que abre o próximo lugar: o telhado das estrelas, a varanda de frente para o mar, o violão e o diário, a sala de respirar, a trilha na floresta com a ioga, a cachoeira e uma surpresa no telhado – e o 8º traz uma garrafa do mar, com a carta do passado dentro. Quando algo abre, uma seta mostra o caminho. A portinha embaixo da máquina de jogos também abre – por enquanto, o armarinho atrás dela está vazio. No telhado das estrelas, uma estrela tocada cai como uma estrela cadente, e o gato fica sentado na almofada.",
