    settings_weather_hint: "Chuva, nuvens ou neve no fundo da tela inicial, conforme o tempo onde você está. Sua localização aproximada fica neste aparelho e é consultada pelo nosso servidor junto ao MET Norway.",
    settings_weather_label: "O tempo no céu da tela inicial",
    weather_failed: "Não deu para consultar o tempo agora.",
    weather_location_denied: "Sem acesso à localização – permita nas configurações do navegador e tente de novo.",
    faq_a_home_focus: "Toque em ◎ no topo da tela inicial: tudo some, menos a única coisa de agora – o que acontece nesta hora, ou a próxima coisa da lista de hoje – com um ✓ grande, e a Nota Rápida. Depois do ✓, aparece a próxima. Toque em 'Modo foco ✕' no topo para trazer tudo de volta.",
    faq_a_home_search: "Abra o menu ☰ – a busca fica bem no alto. Digite pelo menos 2 letras: os resultados vêm das suas notas, lista de compras, calendário, receitas, cadernos (títulos e texto das páginas), metas, tabelas e livros, agrupados por tipo – toque em um para ir direto até ele.",
    faq_a_my_day: "O Meu Dia junta o que antes eram Uma Olhadinha no Dia de Hoje e Minha Rotina, numa só linha do tempo. Na parte de baixo da tela inicial você vê quanto já foi feito, o que é agora ou o próximo (com um ✓ rápido) e, ao lado do título, um copo de água com +1. Toque nele (ou deslize para cima) para abrir o dia inteiro: no topo o que não tem horário, depois tudo por hora – tarefas, eventos e reuniões do calendário, horários fixos da semana, a rotina de hoje, os pequenos passos das suas metas e as refeições do New Me – com uma linha de agora. Filtre por Tarefas, Rotina ou Reuniões e eventos. Um ✓ aqui é o mesmo ✓ em todo lugar (Minha Rotina, Minhas Metas, o calendário) e abre uma margarida no cantinho. 'Editar minha rotina' abre Minha Rotina (também no menu), e '＋ Adicionar para hoje' adiciona uma tarefa para hoje. Um toque no título \"Meu Dia\" (ou na barrinha de cima) fecha de novo.",
