    faq_a_table_shopping_link: "Numa coluna ✓ ligada à lista de compras (como 'Tem ingredientes' em 'Refeições da semana'), cada linha ainda não marcada tem um 🛒. Um toque a adiciona à lista de compras – só uma vez, nunca em dobro. Marque-a aqui ✓ e ela sai da lista; apague-a da lista e aqui ela deixa de aparecer como 'na lista'; marque-a como comprada na lista e a linha aqui ganha o ✓ sozinha. Qualquer coluna ✓ pode ser ligada ou desligada nas configurações da coluna.",
