    nm_plan_monthly_sub: "Cancele quando quiser",
    nm_plan_monthly: "Mensal",
    nm_plan_best: "Mais vantajoso",
    nm_plan_life_sub: "Um pagamento – seu para sempre",
    nm_plan_life: "Vitalício",
    faq_a_new_me_tour: "Logo depois da compra e do questionário curto, um tour rápido mostra o jogo: a barra superior, a próxima missão, o desafio da semana, a mochila mágica e a porta 1 para o quarto secreto. Dá para rever a qualquer momento em ⚙️ Ajustes > 🧭 Tour do New Me – e ali também dá para mudar o nome completo do questionário. Antes da compra, o New Me mostra um 🔒 no menu, e um toque abre uma página com tudo o que está incluído.",
    faq_q_new_me_tour: "Existe um guia do New Me?",
