    nm_gift_intro: "Os {n} desafios, passo a passo. Aqui está o que esperava:",
    nm_gift_title: "Seu presente",
    faq_a_new_me_letter_gift: "No início do New Me (ou depois, em Desafios) dá para escrever uma carta para você no futuro. Depois de lacrada, ela não pode ser lida nem editada até se abrir: na garrafa do mar, no quarto secreto, ou no fim dos 20 desafios – onde também espera um presente.",
    faq_q_new_me_letter_gift: "O que é a carta do passado?",
    faq_a_new_me_challenges: "🏆 Desafios tem 20 desafios: 10 grandes (como 5 dias sem açúcar, uma semana sem carboidratos ou perder 4 kg em um mês – déficit calórico, treino e nada de açúcar todo dia) e 10 mini – pequenos hábitos por uma semana, como café com canela sem açúcar. Ao escolher um desafio, aparece a pergunta de quando começar: hoje, amanhã, semana que vem ou outra data. Um desafio grande e um mini desafio podem rodar ao mesmo tempo. O desafio em andamento aparece no topo do cardápio e no Meu Dia, com um ✓ para o dia. Cada semana de desafio traz um dia livre (🍕) que não quebra o desafio, e um dia não marcado conta como dia livre – dá para marcar hoje e também ontem. Alguns dias se marcam sozinhos: um treino de 20 minutos no Monitoramento de Treinos ou as refeições do cardápio com ✓. Cada desafio tem um ⓘ com o que conta exatamente (por exemplo, a lista completa de carboidratos) – no próprio desafio e ao lado dele no Meu Dia. Abaixo deles, 🌱 Crescimento pessoal tem 48 pequenos desafios de uma semana (eles não contam para os 20) – veja “O que é o desafio da semana?”.",
    faq_q_new_me_challenges: "Como funcionam os desafios do New Me?",
    nm_letter_too_short: "Mais algumas palavras 🙂",
    nm_letter_quiz_note: "Opcional – também dá para escrever depois, em Desafios.",
    nm_letter_write: "✍️ Escrever a carta",
    nm_letter_sealed_line: "Lacrada em {date} · abre depois dos {n} desafios",
    nm_letter_sealed_toast: "Lacrada ✉️ – até a linha de chegada",
    nm_letter_seal_note: "Depois de lacrada, a carta não pode ser lida nem editada até todos os desafios terminarem.",
    nm_letter_seal: "✉️ Lacrar a carta",
    nm_letter_ph: "Onde estou hoje, aonde quero chegar, o que é difícil para mim com a comida, o que gostaria de me dizer na linha de chegada…",
    nm_letter_intro: "Escrita agora e lacrada – ela só abre depois dos {n} desafios, para ver o quanto mudou desde então. Onde estou agora? Quais são minhas metas e o que é difícil para mim com a comida?",
