    nm_ch_completed_label: "desafios concluídos",
    nm_tile_challenges: "Desafios",
    faq_a_workout_calories: "Sim. Cada treino recebe uma estimativa das calorias queimadas – pelo tipo, pela duração e pelo seu último peso (na corrida e no ciclismo também pela velocidade, quando há distância). Ela aparece na lista de treinos e no resumo mensal (Queimadas) e é somada ao orçamento de calorias daquele dia: no Registro Diário de Refeições, nas Métricas de Calorias e Peso e no anel do New Me. É uma estimativa, por isso aparece com ~.",
    faq_q_workout_calories: "Os treinos entram nas minhas calorias do dia?",
    faq_a_new_me_flexible_menu: "Sim. No questionário e nos ajustes escolhe-se quantas refeições por dia – 2 refeições + um lanche / 2 refeições + um jantar leve / 2 refeições + um lanche + um jantar leve – e ➖ no cartão de uma refeição a remove (ficam pelo menos 3); “Voltar ao cardápio” a traz de volta. Em qualquer caso, as calorias do dia continuam as mesmas: o que sai é dividido entre as outras refeições, e cada refeição mostra quanto ganhou e o que pode acompanhar. ✏️ Editar numa refeição abre o texto dela – mude o que quiser (ex.: sem pão ou com mais um ovo) e a IA recalcula as calorias e a proteína. 🔄 Trocar oferece opções do cardápio, ⭐ Salvas e ✨ Escrever; cada mudança pode valer só para hoje ou a partir de agora. E no fim de “O dia todo” há ➕ Adicionar comida – escreva o que foi comido fora do cardápio, e a IA calcula e soma a hoje (✕ apaga).",
