    vision_focus_ribbon: "🎯 Meta do mês",
    vision_tagline: "Grandes metas, pequenos passos.",
    faq_a_app_tour: "O tour abre sozinho uma vez, na primeira vez que você entra. Ele começa pelas suas partes – toque em uma para ir direto até ela – e depois mostra todas as partes do app (a tela inicial, o assistente de IA e cada item do menu) e os cinco grupos de Configurações, cada um com uma explicação curta, e dá uma espiada dentro de alguns (por exemplo, um caminho de meta de exemplo, a mochila e o Google Calendar). Continuar avança, Voltar volta, Pular esta parte vai para a próxima parte e ✕ fecha o tour. Dá para rever quando quiser em Configurações > Ajuda e uso > Tour do app, e continuar de onde parou. Continuar e Voltar ficam sempre no mesmo lugar, na parte de baixo da tela, e no computador as setas do teclado também funcionam.",
    faq_q_app_tour: "Como vejo o tour do app de novo?",
    apptour_done_text: "Alguma dúvida? Ajuda e Perguntas Frequentes, em Configurações, responde tudo, e este tour está sempre disponível em Ajuda e uso.",
