    apptour_s_personalization_text: "País, refeições e lanches por dia, quando começa seu mês financeiro e o que aparece na tela inicial.",
    apptour_s_appearance_text: "Idioma, modo claro ou escuro, temas, fonte, cor do texto, acessibilidade e tamanho do app.",
