    apptour_m_study_link: "🪄 A Divisão Inteligente, no cartão ✅ Tarefas, divide uma tarefa grande em passos no calendário.",
    apptour_m_study_text: "Sua bolsa: um bolso para cada parte da vida – com cadernos, tabelas e tarefas dentro.",
