    apptour_ai_food_link: "Vai direto para o Registro Diário de Refeições e para o total de hoje.",
    apptour_ai_food_text: "Digite o que você comeu – as calorias são estimadas e registradas para você.",
    apptour_newme_short_text: "Abre o New Me – o cardápio de hoje fica direto na tela principal.",
    apptour_ai_link: "Um pequeno 1 sobre ele é o lembrete diário “o que importa hoje”.",
    apptour_ai_text: "Escreva com palavras simples e seu assistente faz o resto: registra calorias, coloca planos no calendário, lê uma receita a partir de uma foto e monta tabelas.",
    apptour_quicknote_link: "📝 e 🛒 abrem as listas completas; 🍎 registra uma refeição salva no Registro Diário de Refeições.",
    apptour_quicknote_text: "Anote algo rapidinho – nas suas Notas ou direto na Lista de Compras.",
    apptour_routine_link: "Um hábito pode registrar um treino no Monitoramento de Treinos automaticamente.",
    apptour_routine_text: "Sua rotina diária por horário, em abas (crianças, estudos, trabalho…). Marque ✓ todo dia para criar hábitos e sequências; 📅 mostra o mês inteiro.",
    apptour_premium_text: "Libera o assistente de IA completo, temas, fontes, Minha bolsa e mais.",
    apptour_note_text: "Um lembrete adesivo para a semana toda. Dentro, a engrenagem ⚙ adiciona uma lista de verificação de 1–3 linhas e muda a cor e o estilo.",
