    table_select_option_delete_confirm: "Esta opção é usada em {count} linhas. Excluí-la? Essas células ficarão vazias.",
    table_select_option_delete_title: "Excluir opção",
    faq_a_other_manual_option: "Em todo lugar onde se escolhe de uma lista de opções, também existe '✏️ Outro' - selecione e digite exatamente o que precisa. Em uma tabela com uma coluna de seleção (por exemplo 'Parentesco' em uma tabela de presentes), toque na célula, escolha '✏️ Outro', digite o valor (por exemplo 'Sobrinho') e toque em Adicionar - ele é salvo como uma nova opção dessa coluna, então na próxima vez já aparece na lista. O pequeno × ao lado de cada opção nessa lista exclui a opção da coluna. Ao escolher o ícone de uma tabela, há muitos ícones (incluindo notas adesivas coloridas). Funciona do mesmo jeito para as categorias de refeições salvas, categorias de receitas, categorias de despesas recorrentes (salva como uma nova categoria pessoal) e categorias de metas em Minhas Metas.",
