    menu_switch_to_tiles: "Mudar para blocos",
    faq_a_receipts_total: "Na tela Notas Fiscais / Recibos, toque em 🧮 'Total de todos os recibos'. Escolha de qual ano até qual ano (por padrão, do recibo mais antigo até este ano), toque em Calcular e aparecerá o total das duas categorias juntas - Despesas domésticas e Despesas de negócio - além de quantos recibos existem e o total de cada categoria separadamente.",
    faq_q_receipts_total: "Como somar todos os recibos de um período?",
    receipts_total_empty: "Nenhum recibo nesses anos.",
