    receipts_total_count: "Recibos: {count}",
    receipts_total_calc_btn: "Calcular",
    receipts_total_to_year: "Até o ano",
    receipts_total_from_year: "Do ano",
    receipts_total_title: "Total de todos os recibos",
    receipts_total_tile: "Total de todos os recibos",
    faq_a_quick_note_apple: "A 🍎 ao lado de 📝 e 🛒 na janela de notas é um atalho para registrar rapidamente uma das suas refeições salvas no Registro Diário de Refeições de hoje. Ela vem ativada por padrão - se não precisar dela, desative-a em Configurações > Personalização e calendário ('Mostrar o atalho 🍎 de refeições salvas na janela de notas') e reative-a ali quando quiser.",
    faq_q_quick_note_apple: "O que é a 🍎 na janela de notas, e dá para ocultá-la?",
    settings_quick_note_apple_label: "Mostrar o atalho 🍎 de refeições salvas na janela de notas",
    faq_a_vision_board_today: "Em Minhas Metas, abaixo do caminho de uma meta (em 'O plano'), toque em 📅 ao lado de um marco e escolha uma data. Você também pode ativar '🔁 Toda semana até concluir' – assim ele volta toda semana no mesmo dia até você marcá-lo uma vez. O marco aparece nesse dia no Meu Dia e no calendário (e no Google Calendar, se estiver conectado), e o botão mostra quando ele está agendado. Um ✓ em qualquer um dos dois lugares marca também no outro e faz o caminho da meta avançar. Toque em 📅 de novo para mudar a data ou removê-lo do calendário. Excluir do calendário uma tarefa que não se repete também exclui o marco da meta; excluir uma semana de um lembrete semanal remove só aquela semana.",
    faq_q_vision_board_today: "Como coloco um marco de uma meta no calendário (📅)?",
    vision_milestone_already_today: "Este marco já está nas tarefas de hoje.",
    auth_consent_required: "Para se cadastrar, é necessário aceitar os Termos de uso e a Política de privacidade.",
    auth_consent_privacy: "Política de privacidade",
    auth_consent_terms: "Termos de uso",
    auth_consent_label: "Li e concordo com os {terms} e a {privacy}, e tenho 16 anos ou mais.",
    nm_bonus_sub: "Uma leitura rápida sobre pesagem, passar da meta e comer fora",
    nm_bonus_label: "Bônus",
    nm_shortcut_title: "New Me – meu cardápio de hoje",
    nm_remove: "Remover",
    nm_split_line: "Plano {plan} · Bebidas {drinks} · Extras {extra}",
    nm_extras_hint: "Do Registro Diário de Refeições e da adição rápida – já contado no anel.",
    nm_extras_title: "Também consumido hoje",
    nm_drinks_total: "{n} / ~{kcal} kcal",
    nm_drink_missing: "Informe o nome da bebida e as calorias",
    nm_drink_more: "+ Outra bebida",
    nm_drink_add: "Adicionar",
    nm_drink_name_ph: "Bebida (ex.: suco)",
    nm_drinks_hint: "Basta digitar a bebida – as calorias são calculadas automaticamente, e o número pode ser alterado.",
    nm_slot_drinks: "Bebidas",
    faq_a_new_me_tracking: "Toque na próxima missão, no alto do New Me, e depois em ✓ Comi para marcar que a próxima refeição já foi feita – o cardápio completo com ✓ em cada refeição está em “O dia todo”, na lateral, e as refeições de hoje também aparecem no Meu Dia, na tela inicial – um toque em uma delas ali (ou o mouse por cima) mostra exatamente o que comer, com ✓ e Trocar. Tudo fica sincronizado com o Registro Diário de Refeições: as refeições do plano, as bebidas e tudo o que você adiciona em outro lugar (por exemplo, um café pela adição rápida) são contados juntos no New Me e no Meu Dia – nada do que você já digitou é sobrescrito, e tirar um ✓ tira só a parte do New Me. Quando todas as refeições do dia estão marcadas, tem uma pequena comemoração. Em “Bebidas”, registre as bebidas do dia – todas juntas até ~150 kcal, ou seja, cerca de 3 bebidas de até ~50 kcal cada. Basta digitar o nome da bebida e as calorias são preenchidas automaticamente por IA. As duas linhas de café/chá também têm um campo “Leite? Quanto?” (por exemplo, “um pouco” ou “50 ml”), e o cálculo se atualiza; o número pode ser mudado antes de adicionar e também depois. Uma bebida com nome e calorias é salva automaticamente assim que você passa para outra coisa – tocar em Adicionar é opcional. Toque em ☆ ao lado de uma bebida para salvá-la como bebida frequente – as bebidas frequentes aparecem como botões no topo do cartão de Bebidas, e um toque as adiciona ao dia. ⭐ salva uma refeição como refeição salva. “Tabela do dia” mostra o que você comeu com calorias e proteína. O pequeno 💎 ao lado do modo foco, no alto da tela inicial, abre o New Me direto. Os valores de calorias e proteína são estimativas de IA e podem conter erros. Não comeu tudo? Embaixo de uma refeição marcada, “Não comeu tudo?” tira um quarto, metade ou três quartos da porção – ou o que você escrever, calculado – e as calorias do dia se atualizam.",
    faq_q_new_me_tracking: "Como funcionam o ✓, as trocas e as calorias no New Me?",
    faq_a_new_me_what: "O New Me é um programa de cardápio diário à parte, com dois planos prontos – 1.300 ou 1.500 calorias – formados por 2 refeições principais e 2 lanches, com 3 opções para cada. Ele inclui todo o Premium. Preço: $11,99 por mês (cancele quando quiser) ou $99,99 uma única vez, vitalício. Abra pelo 💎 New Me no menu. Antes de começar há um questionário curto que começa com um aviso médico que precisa ser aceito. O programa é apenas informação geral e não substitui um médico ou nutricionista clínico.",
    faq_q_new_me_what: "O que é o New Me e como faço para obtê-lo?",
