    routine_overview_no_checks: "Nenhuma marcação neste mês ainda - toque no ✓ ao lado dos itens da sua rotina nos dias em que você os fizer.",
    faq_a_finance_cycle_day: "Por padrão, o resumo do seu orçamento é reiniciado no dia 1º de cada mês do calendário. Se o seu pagamento cai em outro dia (por exemplo, dia 10), defina esse dia aqui - seu resumo mensal, seu histórico e seu orçamento-alvo passam a ir desse dia até o mesmo dia do mês seguinte, em vez do dia 1º até o fim do mês.",
    faq_q_finance_cycle_day: "O que faz a configuração 'Dia de reinício do orçamento mensal'?",
    faq_a_quick_note_view_full_lists: "No menu ☰, Notas e Lista de Compras estão logo ali. Na janela de Nota Rápida (no Modo foco), os pequenos 📝 e 🛒 ao lado de Adicionar também levam até lá, e 🍎 registra rapidinho uma das suas refeições salvas.",
    faq_q_quick_note_view_full_lists: "Como vejo minhas Notas ou minha Lista de compras completas a partir da Nota Rápida?",
