    faq_q_daily_focus_prompt: "O que é o lembretinho que pergunta o que é mais importante eu fazer hoje?", faq_a_daily_focus_prompt: "É um lembrete diário Premium: uma vez por dia, um pequeno selo “1” aparece no ícone do assistente de IA. Toque no selo para abrir um balão perguntando o que é mais importante para você fazer hoje, já com 5 sugestões prontas (elas mudam todo dia, alternando entre temas diferentes ao longo de um ano inteiro para continuarem novas) mais 'Outro' para escrever a sua - dá para escolher mais de uma. Toque em Adicionar, e suas escolhas aparecem como pequenas etiquetas de lembrete no topo de 'Meu Dia' (não são tarefas para marcar). Se você fechar com ✕ ou tocar fora, o selo só fica apagadinho pelo resto do dia em vez de sumir. Vem ativado por padrão, mas você pode desativá-lo em Configurações > Personalização e calendário. Hoje não é o dia? Toque em '🌙 Hoje não' – o selo some até amanhã, quando a pergunta volta como de costume. Uma das sugestões vem da sua própria vida – o próximo passo da sua meta do mês ou a leitura de hoje. Cada dia começa do zero.",
